def refs_section(doc):
    """
    Generate a References section.

    Parameters
    ----------
    doc : dict
        Dictionary produced by numpydoc

    Returns
    -------
    list of str
        Markdown for references section
    """
    if doc['references']:
        refs = doc['references']
    else:
        refs = []

    refs.sort(key=lambda r: r['name'].lower())

    lines = []

    for ref in refs:
        if ref['name']:
            lines.append('%s' % ref['name'])

        if ref['name'] and ref['uri']:
            lines.append(': ')

        if ref['uri']:
            lines.append('[%s]' % ref['uri'])

        if ref['email']:
            lines.append(' <%s>' % ref['email'])

        if ref['uri'] or ref['email']:
            lines.append('')

        if ref['role']:
            lines.append('**Role:** %s' % ref['role'])
            lines.append('')

    return lines

